KG42.register("clusters-e3a9c5ead853414ce1318dfb",{"id":"45-heat_pump_flexibility::v142-d-CL003","paper":"45-heat_pump_flexibility","label":"Uniform-price trading permission, delivery order, and retailer backstop","record":{"cluster_id":"v142-d-CL003","label":"Uniform-price trading permission, delivery order, and retailer backstop","market_meaning":"Buy and sell bid prices obtain trading permission when they meet the uniform market-price threshold, and clearing occurs before actual delivery. The retailer assumes a low-priority buy-and-sell role in the auction; the fixed 1 cent/kWh purchase is retained only as an independent conditional branch for the residual PV scenario described by the source.","mechanism_ids":["v141-a-M01"],"market_types":["LEM"],"process_stages":["activation","matching","clearing"],"scope_disposition":"conditional","scope_explanation":"General price permission, delivery timing, and the retailer backstop each retain their own conditions. Permission does not equal full allocation or physical fulfillment; the fixed purchase price for residual PV is not equivalent to the uniform clearing price, and different clearing rounds for the same delivery period are not merged.","assembly_status":"partial","boundary_rationale":"The buy-and-sell choice in R008 and the trading permission in R007 repeatedly describe the same price-admission condition, while delivery timing supplements its execution boundary. Because the retailer clause is frozen in R008, it is retained as an explicitly restricted branch and is not generalized to all trading conditions.","chain_bindings":[{"chain_id":"v141-c-R007","ownership":"primary","role":"core","rationale":"Carries the pre-delivery process and buy-and-sell permission, retaining the distinction between permission and actual delivery."},{"chain_id":"v141-c-R008","ownership":"primary","role":"core","rationale":"Carries the selection threshold as well as the retailer priority and the specific residual-PV clause."},{"chain_id":"v141-c-R003","ownership":"shared","role":"interface","rationale":"Provides the allocation-permission and accepted-quantity balance interfaces; the clearing subject rules are owned by CL002."}],"connections":[{"connection_id":"v142-d-CL003-L001","from_chain_id":"v141-c-R003","to_chain_id":"v141-c-R008","kind":"alternative_representation","from_refs":["v141-c-R003::phi::v141-c-R003-C006","v141-c-R003::phi::v141-c-R003-C007"],"to_refs":["v141-c-R008::phi::v141-c-R008-C001","v141-c-R008::phi::v141-c-R008-C002"],"evidence_ids":["v141-b-g01-e12"],"rationale":"The buy and sell price permission from the same source is represented separately as clearing allocation authority and as a selection condition; the role difference is retained, and it is not counted twice as two independent admission rules."},{"connection_id":"v142-d-CL003-L002","from_chain_id":"v141-c-R008","to_chain_id":"v141-c-R007","kind":"alternative_representation","from_refs":["v141-c-R008::phi::v141-c-R008-C001","v141-c-R008::phi::v141-c-R008-C002"],"to_refs":["v141-c-R007::phi::v141-c-R007-C004","v141-c-R007::phi::v141-c-R007-C005"],"evidence_ids":["v141-b-g01-e12"],"rationale":"The selection and trading chains repeatedly reference the same price permission; this correspondence does not constitute a new dependency that full execution necessarily follows selection."},{"connection_id":"v142-d-CL003-L003","from_chain_id":"v141-c-R003","to_chain_id":"v141-c-R007","kind":"functional_coupling","from_refs":["v141-c-R003::V::clearing.local","v141-c-R003::phi::v141-c-R003-C009"],"to_refs":["v141-c-R007::V::clearing.local","v141-c-R007::phi::v141-c-R007-C003"],"evidence_ids":["v141-b-g01-e05","v141-b-g01-e06","v141-b-g01-e11"],"rationale":"Accepted quantity is handled by the pre-delivery clearing process, after which the actual energy flow occurs; here only the process and quantity applicability boundaries already present in the source are assembled, and the timing is not upgraded into a performance guarantee."}],"object_mappings":[{"mapping_id":"v142-d-CL003-O001","kind":"same_node","member_refs":["v141-c-R003::V::pricing.local","v141-c-R007::V::pricing.local","v141-c-R008::V::pricing.local"],"canonical_ref":"v141-c-R003::V::pricing.local","display_policy":"single_representative","evidence_ids":["v141-b-g01-e12"],"rationale":"All are uniform-auction price functions; the retailer's fixed residual-PV purchase price is not included in this node's identity mapping."},{"mapping_id":"v142-d-CL003-O002","kind":"same_node","member_refs":["v141-c-R003::V::clearing.local","v141-c-R007::V::clearing.local"],"canonical_ref":"v141-c-R003::V::clearing.local","display_policy":"single_representative","evidence_ids":["v141-b-g01-e05","v141-b-g01-e11"],"rationale":"All reference the same pre-delivery clearing function."},{"mapping_id":"v142-d-CL003-O003","kind":"same_node","member_refs":["v141-c-R003::V::bidding.demand","v141-c-R007::V::bidding.demand"],"canonical_ref":"v141-c-R003::V::bidding.demand","display_policy":"single_representative","evidence_ids":["v141-b-g01-e05","v141-b-g01-e11"],"rationale":"The demand declaration has consistent node identity in clearing and in the delivery timing."},{"mapping_id":"v142-d-CL003-O004","kind":"same_node","member_refs":["v141-c-R003::V::bidding.supply","v141-c-R007::V::bidding.supply"],"canonical_ref":"v141-c-R003::V::bidding.supply","display_policy":"single_representative","evidence_ids":["v141-b-g01-e05","v141-b-g01-e11"],"rationale":"The supply declaration has consistent node identity in clearing and in the delivery timing."},{"mapping_id":"v142-d-CL003-O005","kind":"same_quantity","member_refs":["v141-c-R003::theta::v141-c-R003-theta-p-market","v141-c-R007::theta::p_market","v141-c-R008::theta::theta_uniform_market_price"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g01-e12","v141-b-g03-E02"],"rationale":"All three reference the uniform price threshold of the same auction instance; the different local indices and parameter roles are retained as-is, and prices from multiple clearing rounds are not equated merely because they share the same delivery time."},{"mapping_id":"v142-d-CL003-O006","kind":"same_quantity","member_refs":["v141-c-R003::theta::v141-c-R003-theta-p-bid-i","v141-c-R007::x::p_bid_i"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g01-e12"],"rationale":"All are submitted prices used for threshold comparison by the same buyer in the same auction instance; the given-input role in R003 and the decision-variable role in R007 remain different."},{"mapping_id":"v142-d-CL003-O007","kind":"same_quantity","member_refs":["v141-c-R003::theta::v141-c-R003-theta-p-offer-j","v141-c-R007::x::p_offer_j"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g01-e12"],"rationale":"All are bid prices used for threshold comparison by the same seller in the same auction instance; the local roles of parameter and decision variable are not merged."},{"mapping_id":"v142-d-CL003-O008","kind":"alternative_representation","member_refs":["v141-c-R007::x::p_bid_i","v141-c-R008::x::x_buyer_bid_price"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g01-e12","v141-b-g01-e15"],"rationale":"Both represent the buyer threshold price, but R008 additionally binds a time index and a linear-strategy price domain; these applicability restrictions are not fully aligned, so the alternative expressions are retained."},{"mapping_id":"v142-d-CL003-O009","kind":"alternative_representation","member_refs":["v141-c-R007::x::p_offer_j","v141-c-R008::x::x_seller_offer_price"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g01-e12","v141-b-g01-e15"],"rationale":"Both represent the seller threshold price, but the relationship between the linear-strategy domain in R008 and general seller permission and the retailer role still requires clarification."},{"mapping_id":"v142-d-CL003-O010","kind":"alternative_representation","member_refs":["v141-c-R003::phi::v141-c-R003-C006","v141-c-R007::phi::v141-c-R007-C004","v141-c-R008::phi::v141-c-R008-C001"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g01-e12"],"rationale":"The three items trace to the same buyer price permission, but the result predicates for allocation, trading, and selection differ; the complete constraints are not asserted to be unconditionally equivalent, nor is permission interpreted as actual transaction."},{"mapping_id":"v142-d-CL003-O011","kind":"alternative_representation","member_refs":["v141-c-R003::phi::v141-c-R003-C007","v141-c-R007::phi::v141-c-R007-C005","v141-c-R008::phi::v141-c-R008-C002"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g01-e12"],"rationale":"The three items are different functional representations of the same seller price permission; differences in result semantics and local indices are retained as-is."}],"gaps":[{"gap_id":"v142-d-CL003-G001","category":"upstream_missing","description":"The price threshold grants trading permission; the existing chain does not provide the specific buy-sell matching, accepted quantities, treatment of equal marginal prices, or the complete correspondence from partial execution to delivered quantity.","chain_ids":["v141-c-R003","v141-c-R007","v141-c-R008"],"object_refs":["v141-c-R003::phi::v141-c-R003-C009","v141-c-R007::phi::v141-c-R007-C004","v141-c-R007::phi::v141-c-R007-C005","v141-c-R008::V::matching.counterparties"],"evidence_ids":["v141-b-g01-e05","v141-b-g01-e11","v141-b-g01-e12"],"proposal_ids":[],"required_work":"Upstream verifies and explicitly extracts the correspondence between allocation and delivered quantity; where there is no source support, retain the permission-level meaning and do not presume full execution or a specific matching algorithm."},{"gap_id":"v142-d-CL003-G002","category":"scope_conflict","description":"The retailer's low-priority buy-and-sell role and the fixed purchase of specific residual PV are different scopes. E14 begins with a consequential connective, and the premise context is not provided, so the connection between this fixed price and the general auction transaction price cannot be determined.","chain_ids":["v141-c-R008"],"object_refs":["v141-c-R008::phi::v141-c-R008-C003","v141-c-R008::phi::v141-c-R008-C004","v141-c-R008::theta::theta_retailer_excess_pv_rate"],"evidence_ids":["v141-b-g01-e13","v141-b-g03-E14"],"proposal_ids":[],"required_work":"Supplement the premises and trading path of the reported residual-PV scenario; until then, do not generalize it to all PV sales, equate it with the clearing price, or determine that it necessarily lies outside the LEM."},{"gap_id":"v142-d-CL003-G003","category":"ambiguous_mapping","description":"R008 links the domain of buy-and-sell permission prices to prosumer linear bid trajectories, but the general buy-and-sell threshold also involves the retailer role; the applicable populations and indices of its time-indexed price and R007's non-time-indexed price are not yet fully aligned.","chain_ids":["v141-c-R007","v141-c-R008"],"object_refs":["v141-c-R007::x::p_bid_i","v141-c-R007::x::p_offer_j","v141-c-R008::x::x_buyer_bid_price","v141-c-R008::x::x_seller_offer_price"],"evidence_ids":["v141-b-g01-e04","v141-b-g01-e12","v141-b-g01-e14","v141-b-g01-e15"],"proposal_ids":[],"required_work":"Specify the participant domain, strategy applicability scope, and time index of the price variable, and do not automatically apply the prosumer linear strategy to the retailer's fixed bid."},{"gap_id":"v142-d-CL003-G004","category":"ontology_extension","description":"The frozen graph has no retailer participant and no independent fixed-purchase-price function; the existing related proposal is still unapproved, and the retailer cannot be equated with a local operator or a household prosumer.","chain_ids":["v141-c-R008"],"object_refs":["v141-c-R008::V::matching.counterparties","v141-c-R008::phi::v141-c-R008-C003","v141-c-R008::phi::v141-c-R008-C004"],"evidence_ids":["v141-b-g01-e03","v141-b-g01-e04","v141-b-g01-e13","v141-b-g03-E14"],"proposal_ids":["v141-b-g01-prop-retailer","v141-b-g02-prop-retailer","v141-b-g03-P03"],"required_work":"After manual handling of the proposal and scope differences, upstream revises explicitly; D retains only the proposal reference and does not insert new nodes."},{"gap_id":"v142-d-CL003-G005","category":"ontology_extension","description":"The physical transaction timing in R007 cannot replace the mechanism by which real-time control tracks accepted quantity; corresponding RTC evidence exists, but there is currently no frozen chain for that control function.","chain_ids":["v141-c-R007"],"object_refs":["v141-c-R007::V::execution.energy_trade","v141-c-R007::phi::v141-c-R007-C003"],"evidence_ids":["v141-b-g01-e18","v141-b-g01-e19","v141-b-g02-e11"],"proposal_ids":["v141-b-g01-prop-rtc"],"required_work":"Manually handle the RTC proposal, and have upstream extract the correspondence between control and accepted quantity after authorization; currently, the transaction-execution node is not rewritten as a controller."},{"gap_id":"v142-d-CL003-G006","category":"ambiguous_mapping","description":"Multiple prior clearing rounds and prices may exist for the same delivery period; the current price object has no unified composite identifier of clearing round and delivery period.","chain_ids":["v141-c-R003","v141-c-R007","v141-c-R008"],"object_refs":["v141-c-R003::theta::v141-c-R003-theta-p-market","v141-c-R007::theta::p_market","v141-c-R008::theta::theta_uniform_market_price"],"evidence_ids":["v141-b-g01-e07","v141-b-g01-e12","v141-b-g03-E02"],"proposal_ids":[],"required_work":"Upstream specifies the auction instance, delivery object, and price index; quantity identity mapping is limited to the same aligned auction instance."},{"gap_id":"v142-d-CL003-G007","category":"unverified_source","description":"Trading permission, retailer clauses, and RTC-related materials remain unreviewed candidate evidence.","chain_ids":["v141-c-R003","v141-c-R007","v141-c-R008"],"object_refs":[],"evidence_ids":["v141-b-g01-e05","v141-b-g01-e06","v141-b-g01-e11","v141-b-g01-e12","v141-b-g01-e13","v141-b-g01-e15","v141-b-g01-e18","v141-b-g01-e19","v141-b-g03-E02","v141-b-g03-E14"],"proposal_ids":[],"required_work":"Manually check the source and all conditional mappings; experimental availability must not be stated as passage of independent verification."}]},"rule_refs":["45-heat_pump_flexibility::v141-c-R007","45-heat_pump_flexibility::v141-c-R008","45-heat_pump_flexibility::v141-c-R003"],"unresolved_rule_refs":[],"node_ids":["COMP-89ca1857e29bb0c7","COMP-aa5d858a916162e7","COMP-db31b916ddf1edc2","KG40-12aedc3eec573697","KG40-20f45ec4bdcbac06","KG40-72006c4bf7355110","KG40-a82c49d45641943a"]});
